/**
 * Problem: LeetCode 1979 - Find Greatest Common Divisor of Array
 * Difficulty: Easy
 * Language: JavaScript
 * Author: CodeByTushu
 */
var findGCD = function(nums) {
    let minVal = Infinity;
    let maxVal = -Infinity;

    for (let i = 0; i < nums.length; i++) {
        if (nums[i] < minVal) minVal = nums[i];
        if (nums[i] > maxVal) maxVal = nums[i];
    }

    const gcd = (a, b) => {
        while (b !== 0) {
            const temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    };

    return gcd(minVal, maxVal);
};
